files.theme.css:
:root {
  --background: #ffffff;
  --foreground: #141414;
  --card: #ffffff;
  --card-foreground: #141414;
  --popover: #ffffff;
  --popover-foreground: #141414;
  --secondary: #f5f5f5;
  --secondary-foreground: #141414;
  --muted: #f5f5f5;
  --muted-foreground: #6b6b6b;
  --accent: #f0f0f0;
  --accent-foreground: #141414;
  --border: #e6e6e6;
  --input: #cccccc;
  --destructive: #b91c1c;
  --sidebar: #f5f5f5;
  --sidebar-foreground: #141414;
  --sidebar-primary: #141414;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f0f0f0;
  --sidebar-accent-foreground: #141414;
  --sidebar-border: #e6e6e6;
  --sidebar-ring: #141414;
  --chart-1: #141414;
  --chart-2: #525252;
  --chart-3: #737373;
  --chart-4: #a3a3a3;
  --chart-5: #d4d4d4;
  --primary: #256344;
  --primary-foreground: #ffffff;
  --ring: #256344;
  --radius: 0.375rem;
  --font-sans: ui-sans-serif, system-ui, sans-serif;
  --control-height: 2.25rem;
}
.dark {
  --background: #141414;
  --foreground: #fafafa;
  --card: #1c1c1c;
  --card-foreground: #fafafa;
  --popover: #1c1c1c;
  --popover-foreground: #fafafa;
  --secondary: #262626;
  --secondary-foreground: #fafafa;
  --muted: #262626;
  --muted-foreground: #a3a3a3;
  --accent: #303030;
  --accent-foreground: #fafafa;
  --border: #404040;
  --input: #404040;
  --destructive: #ff9d9d;
  --sidebar: #262626;
  --sidebar-foreground: #fafafa;
  --sidebar-primary: #fafafa;
  --sidebar-primary-foreground: #141414;
  --sidebar-accent: #303030;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-border: #404040;
  --sidebar-ring: #fafafa;
  --chart-1: #fafafa;
  --chart-2: #d4d4d4;
  --chart-3: #a3a3a3;
  --chart-4: #737373;
  --chart-5: #525252;
  --primary: #fafafa;
  --primary-foreground: #141414;
  --ring: #fafafa;
  --radius: 0rem;
  --font-sans: ui-sans-serif, system-ui, sans-serif;
  --control-height: 2rem;
}
